    ["%d day(s) remaining"] = "剩餘 %d 天",
    ["%d recorded spawn points"] = "已記錄 %d 個刷新點",
    ["%s (Rare)"] = "%s（稀有）",
    ["%s is under development."] = "%s 正在開發中。",
    ["**A boss with nothing to collect says so**, in one line."] = "**沒有可收集內容的首領會明確說明**，只用一行文字。",
    ["**Boss kills register in every dungeon.** When the game doesn't report a kill, the addon reads the instance's own objectives and picks it up within seconds."] = "**所有地城都能記錄首領擊殺。** 如果游戲沒有上報擊殺，插件會讀取副本自身的目標，並在幾秒內識別。",
    ["**Bosses you cannot reach no longer hold the count open.** Sinestra outside Heroic and Ra-den in Throne of Thunder now carry a lock."] = "**無法到達的首領不會再讓計數保持未完成。** 非英雄難度下的希奈絲特拉，以及雷電王座中的萊登，現在都會顯示鎖定圖標。",
    ["**Browsing another instance no longer highlights \"current difficulty\".** The white \"needed-now\" color only appears for the instance you are standing in."] = "**瀏覽其他副本時不再高亮“當前難度”。** 白色的“當前需要”顏色只會出現在你實際所在的副本上。",
    ["**Dungeons in the current Mythic+ season are marked.** A \"M+\" tag beside the name, and it follows the rotation on its own with no update needed. This serves as a heads up to avoid Mythic runs that are on seasonal rotation."] = "**當前史詩鑰石賽季的地城會被標記。** 名稱旁會顯示“M+”標籤，並會自動跟隨輪換，無需更新插件。這可以提醒你避免以史詩難度進入當前賽季輪換中的地城。",
    ["**Dungeons!** Initially shipping with 20 dungeons which includes every Classic dungeon plus a couple from MoP. More dungeons will continue to be added! While the routes/guides are being developed for more dungeons, feel free to utilize the transmog browser for ALL dungeons, as well as pink plane navigation to every entrance."] = "**地城！** 首發包含 20 個地城，涵蓋所有經典舊世地城以及幾個熊貓人之謎地城。之後還會繼續增加更多地城！在更多地城的路線/指南開發期間，你仍可使用所有地城的塑形瀏覽器，以及前往每個入口的粉色平面導覽。",
    ["**Every window closes the same way.** The Achievements, Transmog and Skips windows use the same styled close box as the main panel."] = "**所有窗口採用相同的關閉方式。** 成就、塑形和捷徑窗口使用與主面板相同樣式的關閉按鈕。",
    ["**Faction-only bosses are marked.** Uldaman's Lost Dwarves are Horde only, so on Alliance the row shows a lock and the boss count skips them."] = "**陣營專屬首領會被標記。** 奧達曼的失落的矮人僅限部落，因此聯盟角色會在該行看到鎖定圖標，首領計數也會跳過他們。",
    ["**Looks that can no longer be collected are gone from the browser.** Dungeon Set 1 pieces with no boss drops, the Tier 0.5 summons, and season-only rows in modern dungeons. Anything still collectable elsewhere is still listed there."] = "**無法再收集的外觀已從瀏覽器移除。** 包括沒有首領掉落來源的地城套裝 1 部件、0.5 階套裝召喚內容，以及現代地城中的賽季限定行。仍能從其他位置獲得的物品會繼續在對應位置列出。",
    ["**Looks that were missing are back.** Several pieces the Encounter Journal never listed are back, including End Time's Bindings of the End Times and Roogug's Swinesteel Girdle."] = "**之前缺失的外觀已經恢復。** 多件冒險指南從未列出的物品重新加入，包括末日回響中的 Bindings of the End Times，以及 Roogug 的 Swinesteel Girdle。",
    ["**Loot lists are tidier.** Normal and Heroic drops collapse to one row, trash groups by source, shared notes appear once, and token lines lead the list."] = "**戰利品列表更整潔。** 普通和英雄掉落合併為一行，小怪按來源分組，共用說明只顯示一次，代幣行會排在列表前面。",
    ["**Map markers show more.** Rare spawns and certain treasures now show their locations on the map along with a mouseover hint to give a quick status on tracked appearances."] = "**地圖標記顯示更多信息。** 稀有怪和部分寶藏現在會在地圖上顯示位置，鼠標懸停提示還能快速顯示正在追蹤的外觀狀態。",
    ["**Progress persists in dungeons with no lockout.** Normal dungeons keep no lockout, so the game gives an addon nothing to know whether the previous run is still there or if it reset. RetroRuns works it out anyway: log in, reload or walk back in and an active run comes back with every kill in place, while a reset instance starts you at step one on the spot."] = "**無鎖定地城也會保留進度。** 普通地城沒有鎖定，因此游戲不會向插件提供信息來判斷上一次進度是否仍存在或已經重置。RetroRuns 仍能自行判斷：登錄、重載或重新進入後，仍在進行中的一輪會恢復全部擊殺狀態；如果副本已經重置，則會立即從第一步開始。",
    ["**Raid maps mark the NPCs worth knowing about.** Blackrock Foundry's skip-quest NPC and vendor, Icecrown Citadel's tier vendors, Blackwing Lair's alchemy workbenches and the like, each with a hover saying what it is for."] = "**團隊副本地圖會標出值得注意的 NPC。** 黑石鑄造廠的捷徑任務 NPC 和商人、冰冠堡壘的套裝商人、黑翼之巢的煉金工作台等都會被標記，鼠標懸停時會說明用途。",
    ["**Rare, trash and object drops are in the transmog browser.** Rares get a gold \"Rare:\" tag, trash drops get their own section, and Dungeon Set pieces show up on the bosses that drop them. Items that have been removed from the game or have become unobtainable are excluded."] = "**稀有怪、小怪和物件掉落都加入了塑形瀏覽器。** 稀有怪會顯示金色“稀有：”標籤，小怪掉落有獨立分區，地城套裝部件會顯示在掉落它們的首領下。已從游戲中移除或已無法獲得的物品會被排除。",
    ["**RetroRuns has a button on the world map.** It sits in the icon column at the top-right corner alongside other addons' map buttons. Its menu has several map options to toggle, such as hiding POIs you've fully collected or disabling RetroRuns POIs altogether."] = "**RetroRuns 在世界地圖上有自己的按鈕。** 它位於右上角的圖標欄中，與其他插件的地圖按鈕並列。菜單提供多項地圖開關，例如隱藏已全部收集的興趣點，或完全關閉 RetroRuns 的興趣點。",
    ["**Search, everywhere.** The transmog browser, the main panel and the achievements window all have a new magnifying glass. Search by expansion, instance, boss, loot, POI, etc. Whatever you find, one click takes you right to it."] = "**隨處搜索。** 塑形瀏覽器、主面板和成就窗口現在都有新的放大鏡。可按資料片、副本、首領、戰利品、興趣點等搜索。無論找到甚麼，只需點擊一下即可直接前往。",
    ["**Siege of Orgrimmar and newer raids have their lockout tooltip back.**"] = "**決戰奧格瑞瑪以及更新的團隊副本重新顯示鎖定提示。**",
    ["**Smaller fixes.** The Skips window updates on quest turn-in, a finished skip run in a dungeon reads right, the map button closes the map on a second click, loot toasts say \"Browse locked in combat\" instead of erroring, The MOTHERLODE!! travel plane knows both faction entrances, and zoning into a dungeon paints the panel right away."] = "**其他小修復。** 交付任務後捷徑窗口會更新；地城中已完成的捷徑進度會正確顯示；第二次點擊地圖按鈕會關閉地圖；戰利品提示在戰鬥中會顯示“戰鬥中無法瀏覽”而不是報錯；暴富礦區！！的移動平面現在識別雙方陣營入口；進入地城時面板會立即刷新。",
    ["**The achievements window covers dungeons.** A Raids / Dungeons switch sits above the instance list, an instance with nothing to track says so, and a Report button in the footer allows users to flag a solo grade that has gone stale."] = "**成就窗口現在支持地城。** 副本列表上方有團隊副本 / 地城切換；沒有可追蹤內容的副本會明確提示；底部的報告按鈕還能讓用戶反饋已經過時的單刷評級。",
    ["**The idle footer counts your instances.** \"Instance Limit: 3/10 (42m)\" shows how many you've entered against the hourly cap and when the oldest slot frees. Only shows when outside of an instance."] = "**空閒狀態的底欄會統計你的副本次數。** “副本數量限制：3/10 (42m)”顯示你在每小時上限內已經進入了多少次，以及最早的一個名額何時釋放。僅在副本外顯示。",
    ["**The list knows when Timewalking is running.** An hourglass marks the live Timewalking expansion and every instance that offers a run. The hourglass color indicates how much time remains on the event."] = "**列表會識別時光漫游是否正在進行。** 沙漏會標記當前時光漫游資料片以及所有可參與的副本。沙漏顏色表示活動還剩多少時間。",
    ["**The menu dropdowns are rebuilt.** The Transmog, Achievements and Settings dropdowns use the game's current menu system, with a slimmer bar, a magenta arrow and no hover popups."] = "**下拉菜單已重做。** 塑形、成就和設置下拉菜單改用游戲當前的菜單系統，欄位更窄、帶洋紅色箭頭，並取消鼠標懸停彈窗。",
    ["**The nav plane sits beside the raid's name**, instead of beside the difficulty pills."] = "**導覽平面現在位於團隊副本名稱旁邊**，而不是難度標籤旁邊。",
    ["**The panel header is tidier.** Centered wordmark, a magenta underline that survives small UI scales, and \"Run complete!\" on the minimized bar. Text that previously said \"raid\" now says \"instance\"."] = "**面板標題更整潔。** 標誌居中顯示，洋紅色下划線在較小的界面縮放下仍然可見，最小化欄會顯示“本輪完成！”。以前寫作“團隊副本”的文字現在改為“副本”。",
    ["**The panel stays where you put it.** No more creeping up the screen after quitting minimized, and no more collapsing on reload."] = "**面板會留在你放置的位置。** 不會再因為最小化狀態退出而逐漸向屏幕上方偏移，也不會在重載後自行折疊。",
    ["**The transmog browser can open on All classes.** A \"Default Transmog Filter\" setting under General picks whether the browser opens on your class or on every class. The dropdown inside the browser still narrows it per visit."] = "**塑形瀏覽器可以默認顯示所有職業。** “常規”中的“默認塑形篩選”設置可決定瀏覽器打開時顯示你的職業還是所有職業。瀏覽器內部的下拉菜單仍可在每次查看時縮小範圍。",
    ["**The transmog totals count each appearance once**, even when it drops from more than one place."] = "**塑形總數對每個外觀只計算一次**，即使它會從多個位置掉落。",
    ["**Tier upgrade chains read one way everywhere.** Firelands uses the same two-dot chain as every other raid, and the Icecrown Citadel legend explains the dots. Dragon Soul no longer lists every Raid Finder token under every boss."] = "**套裝升級鏈在所有地方採用統一顯示。** 火焰之地使用與其他團隊副本相同的雙點連接方式，冰冠堡壘的圖例會解釋這些點。巨龍之魂也不再在每個首領下列出所有隨機團隊代幣。",
    ["**Timewalking drops get their own \"TW\" pill.** Looks that only drop during Timewalking used to be hidden. Now they show with a TW pill."] = "**時光漫游掉落有專屬“TW”標記。** 過去只在時光漫游期間掉落的外觀會被隱藏。現在它們會帶著 TW 標記顯示。",
