    ["Want to run it again? Zone out and %s."] = "想再刷一次？離開副本並 %s。",
    ["We don't track kill / instance completion achievements unless they are tied to a Meta achievement."] = "除非與元成就相關，否則我們不追蹤首領擊殺 / 副本完成類成就。",
    ["World Map"] = "世界地圖",

    ["|cff9d9d9d(no instance data loaded)|r"] = "|cff9d9d9d（未載入副本資料）|r",
    ["|cffff9333Routing data not yet captured for this instance.|r"] = "|cffff9333尚未收錄這個副本的路線資料。|r",
    -- Sourced names (db2 / TDB verified)
    ["Aaurx"] = "阿魯斯",
    ["Amalgam of Souls"] = "眾魂融合體",
