    ["Ahead to Thok"] = "前往托克",
    ["Ahead to Tortos"] = "前往托爾托斯",
    ["Ahead to Varimathras"] = "前往瓦里瑪薩斯",
    ["Al'Akir also drops {item}, an omnitoken that allows you to purchase any Tier 11 set piece of matching quality. Not tracked here."] = "Al'Akir還會掉落{item}，這是一種萬用徽記，可購買任意同品質的T11套裝部件。此處不追蹤。",
    ["Alchemy Lab"] = "鍊金實驗室",
    ["Alchemy Workbench"] = "煉金工作台",
    ["Amnennar spawns here"] = "Amnennar 在此出現",
    ["Approach ^Tindral^ to trigger the encounter."] = "接近 ^Tindral^ 來觸發戰鬥。",
    ["Approach Felmyst to pull"] = "靠近 Felmyst 開怪",
    ["Approach the boss, and kill the trash to engage ^Rashok^."] = "接近首領，殺死小怪來與^Rashok^交戰。",
    ["Approach the bridge and take a left. Follow the path to ^Oregorger^. Clear trash to spawn the boss."] = "接近橋並向左轉。沿著路徑前往 ^Oregorger^。清除小怪以出現 首領。",
    ["Approach Tindral"] = "接近廷德爾",
    ["Armaments"] = "武器",
    ["Armory"] = "軍械庫",
    ["As you cross the bridge, dodge fire so you don't get thrown over the edge. At the end of the bridge, you will find ^Smolderon^."] = "當你過橋時，躲避火力，這樣你就不會被扔到橋邊。在橋的盡頭，您會發現 ^Smolderon^。",
    ["As you work your way up, stay to the right and follow the path into a room where you will find ^C'Thun^!"] = "上行時靠右，沿路進入一個房間，你會在那裡找到^C'Thun^！",
    ["Aspirant Forudir"] = "Aspirant Forudir",
    ["Aspirant Naradiel"] = "Aspirant Naradiel",
    ["Assembled from 30 Fragments of Val'anyr, which drop across Ulduar; the hammer is forged during the Yogg-Saron encounter."] = "由30個瓦蘭奈爾的碎片組裝而成，這些碎片會在奧杜亞各處掉落；鎚子會在與尤格薩倫的戰鬥中鑄成。",
    ["At bottom go west to Royalty"] = "到底後向西前往Royalty",
    ["At end of path, left to Zigris"] = "走到道路盡頭，左轉去 Zigris",
    ["At the bottom of the elevator, go north to reach the ^Signal Flame^. Click it to trigger a cutscene."] = "到達電梯底部後，向北前往 ^Signal Flame^。點擊它可觸發過場動畫。",
    ["At the bottom of the stairs, talk to Grand Artificer Romuul for several teleport options."] = "在樓梯底部，與大技師羅繆爾交談以獲取幾種傳送選項。",
    ["At the top of the ramp, continue ahead until you reach ^Netherspite^."] = "抵達斜坡頂端後，繼續往前直到抵達 ^Netherspite^。",
    ["At the top of the stairs, clear the elite trash on the platform to spawn ^Garalon^."] = "在樓梯頂部，清除平台上的精英小怪以出現^Garalon^。",
    ["At the top of the stairs, walk through a door and click on the ^Displacement Pad^. After landing, engage ^Lei Shen^."] = "在樓梯頂部，穿過一扇門，然後點擊 ^Displacement Pad^。著陸後，接合^Lei Shen^。",
    ["Avoid blue circles"] = "避免藍色圓圈",
    ["Avoid Sticky Webbing on the ground. The boss will attempt to pull you off the edge with Gossamer Burst. Easiest way to avoid this is to step on a Sticky Webbing before he finishes the cast. When he ascends, follow him up and finish the kill."] = "避免在地面上粘粘帶。 首領 會嘗試用薄紗爆裂將你從邊緣拉出來。避免這種情況的最簡單方法是在他完成石膏固定之前踩上粘性織帶。當他上升時，跟隨他並完成擊殺。",
    ["Awarded together at the end of a long Rogue chain that begins by pickpocketing Hagara the Stormbinder."] = "一條漫長的盜賊任務線最後會同時獎勵這兩件物品，任務從偷竊風暴召喚者哈甲拉開始。",
    ["Back down stairs"] = "回到樓梯下",
    ["Back in ^Hellfire Antechamber^, follow the path to reach ^Gorefiend^. Kill the trash to start the encounter."] = "返回^Hellfire Antechamber^，沿著路徑到達^Gorefiend^。殺死小怪來開始戰鬥。",
    ["Back in ^The Primal Convergence^, follow the newly-opened path to ^Kurog Grimtotem^."] = "返回^The Primal Convergence^，沿著新開啟的路徑到達^Kurog Grimtotem^。",
    ["Back in ^Underhold Nexus^, go straight ahead to another door marked on the map."] = "回到^Underhold Nexus^，直走到地圖上標記的另一扇門。",
    ["Back in the ^Ring of Containment^, head north to the map exit labeled ^Plague Vault^."] = "回到 ^Ring of Containment^，向北前往標記為 ^Plague Vault^ 的地圖出口。",
    ["Back in the ^Underhold Nexus^, take the southern (final) door marked on the map."] = "回到^Underhold Nexus^，走地圖上標記的南門（最後一個）。",
    ["Back in the library, continue up the ramps and open the ^Private Library Door^ to reach ^Shade of Aran^. Note: Killing this boss unlocks a teleport from the entrance NPC to this room, if you need to leave/logout and come back later."] = "回到圖書館後，繼續沿斜坡往上，並打開 ^Private Library Door^ 前往 ^Shade of Aran^。注意：擊殺這個首領後，會解鎖從入口 NPC 傳送到這個房間的功能，方便你離開/登出後稍後回來。",
    ["Back in the main concourse, take the northern exit and go up some stairs."] = "回到主大廳後，從北側出口離開並上幾段樓梯。",
    ["Back in the main lobby, take the northeast exit towards ^Iron Assembly^."] = "回到主大廳，從東北出口朝 ^Iron Assembly^ 方向行駛。",
    ["Back on Antorus, proceed forward and click on one of the ^Lightforged Warframes^ to be flown to the next area."] = "返回安托魯斯後，繼續前進並點擊一台 ^Lightforged Warframes^，飛往下一個區域。",
    ["Back on the main level of ^Astromancer's Rise^, take the northeast exit from the building towards the map exit labeled ^Shal'dorei Terrace^."] = "回到 ^Astromancer's Rise^ 的主層，從建築物的東北出口朝標記為 ^Shal'dorei Terrace^ 的地圖出口走。",
    ["Back outside, follow the path to the east until you reach ^Taran Zhu^."] = "回到室外後，沿路向東直到 ^Taran Zhu^。",
    ["Back through pipe"] = "穿過管道返回",
    ["Back to Core hub"] = "返回核心中心",
    ["Back to courtyard"] = "回到庭院",
    ["Back to Nighthold"] = "返回暗夜堡",
    ["Back to Underhold Nexus"] = "返回地堡樞紐",
    ["Backtrack ahead to Razorscale"] = "原路返回前往鋒鱗",
    ["Backtrack and take ramp down"] = "原路返回並下坡",
    ["Backtrack east, Rotgrip in water"] = "向東返回，Rotgrip 在水中",
    ["Backtrack path to Sartura"] = "原路返回Sartura",
    ["Backtrack south then left to Emalon"] = "向南返回再左轉前往埃瑪爾隆",
