    ["Click Teleporter"] = "點擊傳送器",
    ["Click the ^Disconcerting Bookshelf^ to open a secret passage."] = "點擊 ^Disconcerting Bookshelf^ 打開一條秘密通道。",
    ["Click the ^Downward Draft^ to be flown to the platform and engage ^Dathea, Ascended^."] = "點擊 ^Downward Draft^ 前往平台並參與 ^Dathea, Ascended^。",
    ["Click the ^Hammer of Khaz'goroth^ in the middle of this room after killing ^Demonic Inquisition^."] = "點擊房間中央的 ^Hammer of Khaz'goroth^；需先擊敗 ^Demonic Inquisition^。",
    ["Click the ^Tears of Elune^ in the middle of the room after killing ^The Desolate Host^."] = "點擊房間中央的 ^Tears of Elune^；需先擊敗 ^The Desolate Host^。",
    ["Click the ^Tidestone of Golganneth^ after killing ^Mistress Sassz'ine^."] = "點擊 ^Tidestone of Golganneth^；需先擊敗 ^Mistress Sassz'ine^。",
    ["Click the nearby portal"] = "點擊附近的傳送門",
    ["Click the portal near The Frozen Throne to be teleported near the entrance"] = "點擊冰封王座附近的傳送門，傳送到入口附近",
    ["Click the portal to ^Wellspring Atrium^ to be teleported to the entrance."] = "點擊 ^Wellspring Atrium^ 的傳送門即可傳送到入口。",
    ["Click Tidestone"] = "點擊潮汐石",
