    ["Click Valve then Rotface"] = "點擊閥門，再前往腐面",
    ["Click Valve"] = "點擊閥門",
    ["Cloaks"] = "披風",
    ["Clockwise to Lord Roccor"] = "順時針前往 Lord Roccor",
    ["Conquest sold for gold/silver"] = "征服可用金幣/銀幣購買",
    ["Console then bridge to Vashj"] = "控制台後過橋到 Vashj",
    ["Continue ahead in ^The Forgotten Pool^ until you reach ^Guardian of the Deep^."] = "在 ^The Forgotten Pool^ 中繼續向前，直到到達 ^Guardian of the Deep^。",
    ["Continue ahead into the main courtyard to find ^Spellblade Aluriel^."] = "繼續前進進入主庭院，找到^Spellblade Aluriel^。",
    ["Continue ahead to clear the trash and engage ^King Rastakhan^."] = "繼續清理小怪並參與 ^King Rastakhan^。",
    ["Continue along the path until you reach a room with Ethereal enemies, and take the ramp up."] = "繼續沿路前進，直到抵達有伊斯利敵人的房間，然後沿斜坡上去。",
    ["Continue backtracking through this room."] = "繼續原路穿過這個房間。",
    ["Continue backtracking to main concourse. When you reach it, cut through the platform and take the northeast path out of this room."] = "繼續原路返回主大廳。抵達後，穿過平台並從這個房間的東北路線離開。",
    ["Continue climbing"] = "繼續往上",
    ["Continue climbing."] = "繼續往上。",
    ["Continue down spiral"] = "繼續螺旋式下降",
    ["Continue down the path and clear the trash to spawn ^The Amalgamation Chamber^."] = "繼續沿著路徑前進並清除小怪以出現 ^The Amalgamation Chamber^。",
    ["Continue down the stairs until you reach the room with ^Archaedas^. Activate the ^Altar of Archaedas^ to begin the fight."] = "繼續下樓，直到到達有 ^Archaedas^ 的房間。激活 ^Altar of Archaedas^ 開始戰鬥。",
    ["Continue down the stairs, and follow the linear path to the south side of the map. Jump down to engage ^Gekkan^."] = "下樓並沿單一路線前往地圖南側。跳下去與 ^Gekkan^ 交戰。",
    ["Continue down the stairs, following the path until you reach ^Sisters of the Moon^."] = "繼續走下樓梯，沿著小路直到到達 ^Sisters of the Moon^。",
    ["Continue following the linear path into the next room."] = "繼續沿著直線路徑進入下一個房間。",
    ["Continue following the path ahead to reach ^Sennarth^."] = "繼續沿著前面的路到達^Sennarth^。",
    ["Continue following the path ahead to reach ^Terros^."] = "繼續沿著前面的路到達^Terros^。",
    ["Continue following the path through the waves of ^Hoplings^ until you reach ^Hoptallus^. Clear the trash to spawn the boss."] = "繼續沿路穿過一波波 ^Hoplings^，直到 ^Hoptallus^。清掉小怪以召出首領。",
    ["Continue following the path to arrive back at the ^The Primal Bulwark^."] = "繼續沿著路徑返回^The Primal Bulwark^。",
    ["Continue following the path to engage ^Fetid Devourer^."] = "繼續按照路徑參與 ^Fetid Devourer^。",
    ["Continue following the path to reach ^Vectis^."] = "繼續沿著路徑到達 ^Vectis^。",
    ["Continue following the path to reach ^Zek'voz, Herald of N'Zoth^. Clear trash to start the encounter."] = "繼續沿著路徑到達 ^Zek'voz, Herald of N'Zoth^。清除小怪以開始戰鬥。",
    ["Continue forward to ^The Jailer^'s platform and end this."] = "繼續前進到^The Jailer^的平台並結束這一切。",
    ["Continue north through the ^Opera Hall Balcony^ and climb the ramp at the end."] = "繼續往北穿過 ^Opera Hall Balcony^，並在盡頭沿斜坡上去。",
    ["Continue south to the elevator and take it down."] = "繼續向南前往電梯並搭乘向下。",
    ["Continue south until the path ends, and take a left to follow the path east until you reach ^Quartermaster Zigris^ walking around."] = "繼續向南直到道路盡頭，然後左轉沿道路向東，直到找到正在巡邏的 ^Quartermaster Zigris^。",
    ["Continue straight ahead on the southern path and you will run right into ^Thruk^."] = "沿南側道路徑直向前，很快就會遇到 ^Thruk^。",
    ["Continue straight ahead to engage ^Conclave of the Chosen^."] = "繼續直行接合^Conclave of the Chosen^。",
    ["Continue to Blackhand"] = "繼續黑手",
    ["Continue to Gruul"] = "繼續前往 Gruul",
    ["Continue up and around the stairwell until you reach ^Tichondrius^."] = "繼續沿著樓梯間向上走，直到到達 ^Tichondrius^。",
    ["Continue up path to exit right"] = "沿路上行到右側出口",
    ["Continue up the ramp and clear the ogres. Use ^Omokk's Head^ while standing over ^Urok's Tribute Pile^ to summon ^Urok Doomhowl^. You can {skip} this boss if you want."] = "沿坡道上去並清理食人魔。使用 ^Omokk's Head^ 時站在 ^Urok's Tribute Pile^ 上，即可召喚 ^Urok Doomhowl^。如果願意，可以 {skip} 這個首領。",
    ["Continue up the ramp and keep to the left, bypassing ^Urok's Tribute Pile^. Follow the ramp as it turns sharply back to the south."] = "繼續沿坡道上行並靠左，繞過 ^Urok's Tribute Pile^。沿坡道前進，坡道急轉後向南。",
    ["Continue up the ramp/stairs"] = "沿斜坡/樓梯繼續往上",
    ["Continue up the spiral stairwell."] = "繼續沿螺旋樓梯往上。",
    ["Continue up the stairs into ^The Grand Ballroom^. Take a left into ^The Banquet Hall^ and find ^Moroes^ up on a small platform."] = "繼續上樓進入 ^The Grand Ballroom^。左轉進入 ^The Banquet Hall^，在一個小平台上找到 ^Moroes^。",
    ["Continue up the stairs"] = "繼續上樓",
    ["Continue up the stairs. When you reach the top, follow the path to ^Mother Shahraz^."] = "繼續上樓。抵達頂端後，沿路前往 ^Mother Shahraz^。",
    ["Continue working your way towards the central hub. When you get there, take the first path on the left and take the portal to ^Grizzly Hills^."] = "繼續朝中央樞紐前進。當你到達那裡時，走左邊的第一條路，然後通過傳送門到達^Grizzly Hills^。",
    ["Continue working your way up the ramp and stairs."] = "繼續沿斜坡和樓梯往上。",
    ["Crafted from the Bindings of the Windseeker. Garr and Baron Geddon each drop one half."] = "由逐風者的束縛製成。加爾與迦頓男爵各掉落一半。",
    ["Crafted from the Eye of Sulfuras, a rare drop from Ragnaros."] = "由薩弗拉斯之眼製成，這是拉格納羅斯的稀有掉落。",
    ["Cross Bridge Ahead"] = "前方過橋",
    ["Cross bridge, downstairs to Inner Sanctum"] = "過橋下樓前往內殿",
    ["Cross lava bridge"] = "穿過熔岩橋",
    ["Cross Lava to Neltharion's Sanctum"] = "穿越熔岩前往奈薩里奧的聖殿",
    ["Cross the bridge behind ^Anduin^ to the teleporter. Select ^Proceed^."] = "穿過 ^Anduin^ 後面的橋到達傳送器。選擇^Proceed^。",
    ["Cross the room and take the southern exit."] = "穿過房間並從南出口走。",
    ["Cross to Maiden"] = "穿越到少女",
    ["Crusader Grimtong"] = "十字軍格里姆通",
    ["Crusader Halford"] = "十字軍哈爾福德",
    ["Deactivate first shield generator"] = "關閉第一個護盾發生器",
    ["Death by lava near Slagmaw"] = "在 Slagmaw 附近用熔岩自殺",
    ["Destroy Bells"] = "摧毀鐘聲",
    ["Destroy Cannons"] = "摧毀大炮",
    ["Dialog then Anduin"] = "對話然後安杜因",
    ["Dialog then Portal"] = "對話然後傳送門",
    ["Dialog then Raszageth"] = "對話然後拉薩格斯",
    ["Dialog then Shriekwing"] = "對話然後尖叫之翼",
    ["Dialog then Sludgefist"] = "先是對話，然後是泥拳",
    ["Dialog then Sylvanas"] = "對話然後希爾瓦娜斯",
    ["Dialog then Titan Console"] = "對話框然後是泰坦控制台",
    ["Displacement Pad"] = "位移墊",
    ["Do not attack ^Razorgore^ directly or you will wipe. To start the encounter properly, kill the adds on the opposite platform. Immediately click the ^Orb of Domination^ to mind control the boss. As quickly as you can, destroy all eggs in the room. You can do this by walking to each one and pressing the action button for ^Destroy Egg^. After you've killed the last egg, the mind control will end and you can kill ^Razorgore^. If you run out of time, kill adds and click the orb again to finish off the remaining eggs."] = "不要直接攻擊^Razorgore^，否則會滅團。要正確開始戰鬥，先擊殺對面平台上的小怪。立即點擊^Orb of Domination^心控首領。盡快摧毀房間裡所有龍蛋。走到每個龍蛋旁，按下^Destroy Egg^的動作按鈕。摧毀最後一個龍蛋後，心控會結束，你就可以擊殺^Razorgore^。如果時間不夠，擊殺小怪並再次點擊寶珠，處理剩餘龍蛋。",
    ["Door"] = "門",
    ["Down cliffside then west to Princess"] = "沿峭壁下去，然後向西到 Princess",
    ["Down hallway, left to Halycon"] = "沿走廊下去，左轉去 Halycon",
    ["Down ramp to Illhoof"] = "下坡前往 Illhoof",
    ["Down ramp to Mol'dar"] = "沿坡道下去到 Mol'dar",
    ["Down ramp, go left"] = "沿坡道下去，左轉",
    ["Down spiral to Shad'har"] = "螺旋下降到夏德哈",
    ["Down stairwell"] = "下樓梯間",
    ["Down to Cenarius"] = "下到塞納留斯",
    ["Down to Cho"] = "下到曹",
    ["Down to Kil'jaeden"] = "往下前往 Kil'jaeden",
    ["Down to Sisters"] = "下到姐妹們",
    ["Downstairs across to Magmaw"] = "下樓前往熔喉",
    ["Downstairs to kill Gandling"] = "下樓擊殺 Gandling",
    ["Dragons then Khadgar"] = "先是龍，然後是卡德加",
    ["Dragons"] = "龍",
    ["Draven Starts Sludgefist"] = "德萊文開始泥拳",
    ["Drops from Druid of the Fang"] = "由尖牙德魯伊掉落",
    ["During dance phase, run to the spotlight. Walk in the direction of the other NPCs a few times. Jump to clear debuff stacks."] = "舞蹈階段跑到聚光燈下。跟著其他 NPC 的方向移動幾次。跳躍以清除減益層數。",
    ["East exit to Flamelash"] = "從東側出口到 Flamelash",
    ["East Exit"] = "東口",
    ["East path to Karathress"] = "東側路線前往 Karathress",
    ["East path to Wyrmthalak"] = "沿東側道路到 Wyrmthalak",
