    ["East then South to Valithria"] = "向東再向南前往踏夢者",
    ["East then South"] = "先東後南",
    ["East to Aarux"] = "向東到 Aarux",
    ["East to Aku'mai"] = "向東到 Aku'mai",
    ["East to Ancient Stone Keeper"] = "向東到 Ancient Stone Keeper",
    ["East to chest then stairs"] = "向東到寶箱，再走樓梯",
    ["East to Console then Algalon"] = "向東前往控制台，再前往奧爾加隆",
    ["East to Elevator"] = "東至電梯",
    ["East to elevator"] = "向東到電梯",
    ["East to Eranikus"] = "向東到 Eranikus",
    ["East to Gorefiend's Vigil"] = "往東前往 Gorefiend's Vigil",
