    ["East to Taran Zhu"] = "向東到 Taran Zhu",
    ["East to Xhul'horac"] = "東至祖霍拉克",
    ["East towards Brutallus"] = "往東前往 Brutallus",
    ["Ebon Blade Acolyte"] = "黑鋒侍僧",
    ["Eiendormi on Right"] = "右邊的艾恩多爾密",
