    ["Elevator"] = "電梯",
    ["Elunaria Portal"] = "艾露納里亞傳送門",
    ["Emerald Nightmare Portal"] = "翡翠夢魘傳送門",
    ["Ensign Roberts"] = "羅伯茲少尉",
    ["Enter building"] = "進入建築",
    ["Enter Cleft of Shadows"] = "進入陰影裂縫",
    ["Enter Gates of Org"] = "進入組織之門",
    ["Enter Molten Crucible"] = "進入熔爐",
    ["Enter the next room and kill ^Drest'agath^."] = "進入下一個房間並殺死^Drest'agath^。",
    ["Enter the room to engage with ^The Hivemind^."] = "進入房間與 ^The Hivemind^ 互動。",
    ["Enter the water and click the ^Oxygen-Rich Membrane^ for swim speed and water breathing. You must kill the last trash pack in the tunnel to spawn ^Blackwater Behemoth^."] = "進入水中並點擊 ^Oxygen-Rich Membrane^ 查看游泳速度和水中呼吸。您必須殺死隧道中的最後一個小怪群才能出現 ^Blackwater Behemoth^。",
    ["Escort ^Muyoh^, stopping two times on the way to the final boss, ^Mutanus the Devourer^. Kill several waves of trash and the boss will spawn."] = "護送 ^Muyoh^，途中停兩次，直到最終首領 ^Mutanus the Devourer^。擊殺數波小怪後首領會出現。",
    ["Escort Muyoh to Mutanus"] = "護送 Muyoh 到 Mutanus",
    ["Escort Muyoh"] = "護送 Muyoh",
    ["Essence of Eonar"] = "伊歐娜精華",
    ["Essence Tokens"] = "精華徽記",
    ["Exit and take second right"] = "離開後在第二個路口右轉",
    ["Exit building to south"] = "從建築南側出去",
    ["Exit east, then up the ramp"] = "往東離開後上坡",
    ["Exit library then left"] = "離開圖書館後左轉",
    ["Exit northeast to ramp"] = "東北出口到斜坡",
    ["Exit Portal Nearby"] = "附近的出口入口",
    ["Exit portal nearby."] = "出口傳送門就在附近。",
    ["Exit portal to the east"] = "向東走出傳送門",
    ["Exit South"] = "南側出口",
    ["Exit southwest to Lord Incendius"] = "從西南出口到 Lord Incendius",
    ["Exit the ship"] = "離開飛艇",
    ["Exit the water, and walk back through the water channel until you reach ^Twilight Lord Bathiel^."] = "離開水中，沿水道往回走，直到到達 ^Twilight Lord Bathiel^。",
    ["Exit tram to Mimiron"] = "下軌道車前往米米爾隆",
    ["Exit via Stairwell"] = "經由樓梯間離開",
    ["Expedition Commander"] = "遠征隊指揮官",
    ["Fall then path to Uu'nat"] = "墜落，然後通往烏納特",
    ["Far path right to Lord Overheat"] = "沿最右側道路到 Lord Overheat",
    ["Feel free to return and kill any bosses you skipped!"] = "你可以隨時返回並擊殺先前跳過的首領！",
    ["Find Auriaya circling"] = "找到繞場巡邏的歐爾莉亞",
    ["Find Fineous patrolling ramps"] = "找到在坡道巡邏的 Fineous",
    ["Find the teleporter behind ^Lihuvim^ and select ^Domination's Grasp^."] = "找到 ^Lihuvim^ 後面的傳送器並選擇 ^Domination's Grasp^。",
    ["Firestone Vendor"] = "火石商人",
    ["First exit on right"] = "從右側第一個出口出去",
    ["First left to Skorpyron"] = "第一個路口左轉前往斯考匹隆",
    ["Fish up The Lurker Below"] = "釣起 The Lurker Below",
    ["Fishing"] = "釣魚",
    ["Flamegor ahead"] = "直走前往Flamegor",
    ["Fly Here"] = "飛到這裡",
    ["Fly into Sky Portal"] = "飛入天空之門",
    ["Follow ^Akama^ into the next area. Talk to him to start the final battle against ^Illidan Stormrage^."] = "跟隨 ^Akama^ 進入下一區域。與他交談，開始與 ^Illidan Stormrage^ 的最終戰鬥。",
    ["Follow Path Ahead"] = "遵循前進的道路",
    ["Follow path to Bathiel"] = "沿路到 Bathiel",
    ["Follow path to Gu Cloudstrike"] = "沿路到 Gu Cloudstrike",
    ["Follow path to Harlan"] = "沿路到 Harlan",
    ["Follow path to Hoptallus"] = "沿路到 Hoptallus",
    ["Follow path to Lethtendris"] = "沿路到 Lethtendris",
    ["Follow path to Lucifron"] = "沿路前往Lucifron",
    ["Follow path to Noxxion"] = "沿路到 Noxxion",
    ["Follow path to Omokk"] = "沿路到 Omokk",
    ["Follow path to Pa'valak"] = "沿路到 Pa'valak",
    ["Follow path to Revelosh"] = "沿路到 Revelosh",
    ["Follow path to Ring of Law"] = "沿路到 Ring of Law",
    ["Follow path to Vosh'gajin"] = "沿路到 Vosh'gajin",
    ["Follow path"] = "遵循路徑",
    ["Follow path, jump down to Gekkan"] = "沿路前進，跳下到 Gekkan",
    ["Follow paths to Angerforge"] = "沿道路到 Angerforge",
    ["Follow the foundry floor to ^Prototype Pantheon^."] = "沿著鑄造車間前往^Prototype Pantheon^。",
    ["Follow the map from the entrance to ^The Tarragrue^."] = "從入口按照地圖前往 ^The Tarragrue^。",
    ["Follow the mineshaft into the next room. After a lengthy dialog, speak to ^Norushen^ to start the encounter."] = "沿著礦井進入下一個房間。經過漫長的對話後，與 ^Norushen^ 交談以開始戰鬥。",
    ["Follow the path all the way back to find ^Il'gynoth, Corruption Reborn^."] = "沿著路徑一路返回即可找到^Il'gynoth, Corruption Reborn^。",
    ["Follow the path all the way back to meet the ^Council of Dreams^. Click each of the illusions to start the fight."] = "沿著小路一路返回即可見到^Council of Dreams^。點擊每個幻象即可開始戰鬥。",
    ["Follow the path and kill ^Braekkas^ to open the wall. Continue on to find ^The Primal Council^."] = "沿著路徑殺死^Braekkas^來開啟牆壁。繼續找到^The Primal Council^。",
    ["Follow the path around to ^Hellfire High Council^."] = "沿著路徑前往 ^Hellfire High Council^。",
    ["Follow the path back out to the main courtyard, and make your way to the ^Captain's Quarters^ entrance on the southwest corner of the map. Inside the ^Captain's Quarters^, take your first right to go up a short stairwell."] = "沿著小路返回主庭院，然後前往地圖西南角的 ^Captain's Quarters^ 入口。在 ^Captain's Quarters^ 內，在第一個路口右轉，走上一個短樓梯間。",
    ["Follow the path down to ^Skolex^. Kill the trash to spawn the boss."] = "沿著路徑向下到達 ^Skolex^。殺死小怪來出現 首領。",
    ["Follow the path east to reach the final boss, ^Overlord Wyrmthalak^."] = "沿道路向東到達最終首領 ^Overlord Wyrmthalak^。",
    ["Follow the path south and continue on to ^The Illidari Council^."] = "沿路往南並繼續前往 ^The Illidari Council^。",
    ["Follow the path through ^The Endless Foundry^, killing the trash on the way to ^Lihuvim^."] = "沿著 ^The Endless Foundry^ 的路徑前進，消滅前往 ^Lihuvim^ 途中的小怪。",
    ["Follow the path through ^The Grand Design^, killing trash on the way to ^Lords of Dread^."] = "沿著 ^The Grand Design^ 的路徑前進，在通往 ^Lords of Dread^ 的路上消滅小怪。",
    ["Follow the path through the armory until you reach ^Armsmaster Harlan^."] = "沿軍械庫道路前進，直到到達 ^Armsmaster Harlan^。",
    ["Follow the path through the next area until you reach ^Teron Gorefiend^."] = "沿路穿過下一區域，直到抵達 ^Teron Gorefiend^。",
    ["Follow the path to reach the ^Ascendant Council^."] = "沿著路徑到達 ^Ascendant Council^。",
    ["Follow the path to the boss area, and clear the trash to spawn ^Volcoross^."] = "沿著路徑前往 首領 區域，清除小怪以出現 ^Volcoross^。",
    ["Follow the path to the final map exit labeled ^N'Zoth^. Kill adds on the bridge to spawn a portal at the end."] = "沿路前往標有 ^N'Zoth^ 的最後一個地圖出口。清理橋上的小怪，在橋盡頭召出傳送門。",
    ["Follow the path to the map exit labeled ^The Hive^."] = "沿著路徑前往標記為 ^The Hive^ 的地圖出口。",
    ["Follow the path up and to the left to reach ^Tectus^. Kill the (3) rock golems to spawn the boss."] = "沿著路徑向上並向左行駛即可到達 ^Tectus^。殺死 (3) 個岩石傀儡來出現 首領。",
    ["Follow the path up the stairs and around to the map exit labeled ^Halls of Opulence^. Jump in the hole at the end of the path."] = "沿著樓梯向上並繞行至標有 ^Halls of Opulence^ 的地圖出口。跳進路盡頭的洞裡。",
    ["Follow the path up to ^Broodkeeper Diurna^."] = "沿著路徑一直走到 ^Broodkeeper Diurna^。",
    ["Follow the path. Once you reach the boss room, kill the final trash pack and talk to ^Lorewalker Cho^ to trigger the boss fight with ^Elegon^."] = "遵循路徑。到達首領房間後，殺死最後一個小怪群並與 ^Lorewalker Cho^ 交談以觸發與 ^Elegon^ 的首領戰鬥。",
    ["Font of Power"] = "能量之泉",
    ["For the knockback, position yourself between the boss and a tornado."] = "為了擊退，請將自己置於 首領 和龍捲風之間。",
    ["Formation Seed"] = "成形之種",
    ["Forward then left to Ignis"] = "向前再左轉前往掌爐者",
    ["Forward to Imonar"] = "轉發至伊莫納爾",
    ["From ^The Primal Convergence^, follow the path to the entrance labeled ^Iceskitter Hollow^."] = "從 ^The Primal Convergence^ 出發，沿著路徑前往標有 ^Iceskitter Hollow^ 的入口。",
    ["From ^Wellspring Atrium^, take the final remaining exit labeled ^Throne of the Firelord^. Click on the ^Formation Seed^ to construct a bridge to the next area."] = "從 ^Wellspring Atrium^ 出發，走最後一個標記為 ^Throne of the Firelord^ 的出口。點擊 ^Formation Seed^ 構建通往下一個區域的橋梁。",
    ["From Andorgos"] = "來自 Andorgos",
    ["From Arygos"] = "來自 Arygos",
    ["From Kandrostrasz"] = "來自 Kandrostrasz",
    ["From Keyl Swiftclaw"] = "來自 Keyl Swiftclaw",
    ["From Merithra of the Dream"] = "來自 Merithra of the Dream",
    ["From the bottom of the stairs, take a hard left and descend into the tunnels."] = "到樓梯底部後大幅左轉，向下進入隧道。",
    ["From the top of the elevator, proceed ahead up the ramp to find the ^Antoran High Command^."] = "從電梯頂部，沿著坡道繼續前行，找到 ^Antoran High Command^。",
    ["From the top of the stairs, take your first right. Travel east down the hallway until you reach ^Maiden of Virtue^."] = "從樓梯頂端第一個路口右轉。沿走廊往東，直到抵達 ^Maiden of Virtue^。",
    ["From Vethsera"] = "來自 Vethsera",
    ["From Warden Haro"] = "來自 Warden Haro",
    ["Fyrakk additionally drops {item}, an omnitoken that exchanges for any tier slot. Not tracked here."] = "菲拉卡還會掉落 {item}，這是一種可兌換任意套裝部位的全能代幣。本插件不追蹤該物品。",
    ["Galewind Crag then Upward Draft"] = "狂風峭壁然後向上吃水",
    ["Garrosh also drops {tokens}, which are omnitokens that allow you to purchase any Tier 16 set piece of matching quality. Not tracked here."] = "Garrosh還會掉落{tokens}，這是一種萬用徽記，可購買任意同品質的T16套裝部件。此處不追蹤。",
    ["Gauntlet then Dragons"] = "手套然後龍",
    ["General Draven"] = "德瑞文將軍",
    ["Go activate The Shadowforge Lock"] = "去激活 The Shadowforge Lock",
    ["Go Down Elevator"] = "搭升降梯下行",
    ["Go down elevator"] = "搭電梯下去",
    ["Go down the stairs and kill ^Darkmaster Gandling^ to complete the run."] = "下樓並擊殺 ^Darkmaster Gandling^，即可完成本次路線。",
    ["Go Here"] = "去這裡",
    ["Go right to Avatar of Hakkar"] = "向右前往 Avatar of Hakkar",
    ["Go southwest through building"] = "穿過建築向西南",
    ["Go up ramp"] = "上斜坡",
    ["Go up the stairs and face ^Master Snowdrift^ next."] = "上樓，接下來對付 ^Master Snowdrift^。",
    ["Goraluk Anvilcrack"] = "戈魯魯克·裂砧",
    ["Grand Ballroom north stairs"] = "Grand Ballroom 北側樓梯",
    ["Graveyard"] = "墓地",
    ["Grizzly Hills Portal"] = "灰熊丘陵傳送門",
    ["Halion in Middle"] = "哈里昂在中央",
    ["Hans & Franz"] = "漢斯和弗朗茲",
    ["Head down the long hallway to the teleporter. Select ^Ephemeral Plains Alpha^."] = "沿著長長的走廊前往傳送器。選擇^Ephemeral Plains Alpha^。",
    ["Head west and click the ^Keystone^ in the small green model buildings. After a short scripted sequence, ^Ironaya^ will emerge from the door."] = "向西前進，點擊小型綠色模型建築中的 ^Keystone^。經過短暫劇情後，^Ironaya^ 會從門中出現。",
    ["Head"] = "頭部",
    ["Heal or bandage the boss to defeat this encounter. If you want to skip her, run along the outer edge of the room without pulling anything on your way to the elevator."] = "治療首領或對其使用繃帶以完成戰鬥。若要跳過她，沿房間外緣前往電梯，途中不要引到任何敵人。",
    ["Heal or bandage the boss to defeat this encounter. If you want to {skip} her, run along the outer edge of the room without pulling anything on your way to the elevator."] = "治療或替首領繃帶即可完成這場戰鬥。如果想要{skip}她，就沿房間外圈跑向電梯，不要引到任何怪。",
    ["Hole Behind Neltharion"] = "奈薩里奧後面的洞",
    ["Hole to East"] = "洞向東",
    ["Hydrospawn ahead in water"] = "前方水中是 Hydrospawn",
    ["If you end up in the maze phase, collect a green orb and use it to bring down the barrier. Movement abilities can be used to get through the maze if needed."] = "如果您最終進入迷宮階段，請收集一個綠色球體並用它來拆除障礙物。如果需要，可以使用移動能力來穿過迷宮。",
    ["In ^Halls of the Faithful^, wind your way around to the room overlooking the dancers. Clear the trash, and the NPCs will enter the room and open both gates. Follow the path opened by ^Prince Renathal^, and make your way up the stairs to ^Pride's Prison^."] = "在 ^Halls of the Faithful^ 中，蜿蜒前往俯瞰舞者的房間。清理小怪，NPC 將進入房間並開啟兩扇門。沿著 ^Prince Renathal^ 開啟的路徑，爬上樓梯到達 ^Pride's Prison^。",
    ["In ^The Arachnid Quarter^, take your first left and follow the path to ^Anub'Rekhan^."] = "在 ^The Arachnid Quarter^ 中，第一個路口左轉並沿路前往 ^Anub'Rekhan^。",
    ["In Dalaran"] = "在達拉然",
    ["In Mount Hyjal"] = "在海加爾山",
    ["In the ^Chamber of the Avatar^, move forward and kill trash to open the door, then watch some dialog before engaging with ^Fallen Avatar^."] = "在 ^Chamber of the Avatar^ 中，向前移動並殺死小怪以開啟門，然後在與 ^Fallen Avatar^ 互動之前觀看一些對話。",
    ["In the ^Chapel Gardens^, follow the path south to find ^Brother Korloff^ patrolling around."] = "在 ^Chapel Gardens^ 中，沿道路向南找到正在巡邏的 ^Brother Korloff^。",
    ["In the boss room, kill all of the trash and approach the boss to start the encounter with ^Kormrok^."] = "在首領房間裡，殺死所有小怪並接近首領，開始與^Kormrok^的戰鬥。",
    ["In the large outdoor area, make your way up the middle path to ^Supremus^."] = "在大型戶外區域，沿中間路線往上前往 ^Supremus^。",
    ["In the next area, clear the trash before, on, and after the platform to force ^Gara'jal the Spiritbinder^ into combat."] = "在下一個區域，清除平台前、平台上和平台後的小怪，迫使^Gara'jal the Spiritbinder^進入戰鬥。",
    ["In the next area, continue following the path until you reach ^Blood-Queen Lana'thel^."] = "在下一個區域繼續沿路前進，直到到達^Blood-Queen Lana'thel^。",
    ["In the next area, continue west and you'll run straight into ^Immol'thar^. You can deactivate the remaining two ^Shield Generators^ if you need to for a quest, but they are not required."] = "進入下一區域後繼續向西，會直接遇到 ^Immol'thar^。如果任務需要，可以關閉剩餘兩個 ^Shield Generators^，但並非必須。",
    ["In the next area, follow the path around a few turns and up some stairs, killing trash on your way to ^Malkorok^."] = "在下一個區域，沿著小路轉幾個彎，爬上一些樓梯，在前往 ^Malkorok^ 的路上消滅小怪。",
    ["In the next area, follow the path to click a portal being channeled by ^Archmage Khadgar^."] = "在下一個區域中，按照路徑點擊由 ^Archmage Khadgar^ 引導的傳送門。",
    ["In the next area, follow the path upstairs to the right and follow it around."] = "在下一個區域，沿著樓上的路向右走，然後沿著它走一圈。",
    ["In the next area, go east, then south down some stairs. When you reach the boss room, clear the trash to start the encounter with ^Socrethar the Eternal^."] = "在下一個區域，向東走，然後向南走一些樓梯。當你到達首領房間時，清除小怪即可開始與^Socrethar the Eternal^的戰鬥。",
    ["In the next area, head north then go down the stairs on your left. Follow this path until you reach ^Gurtogg Bloodboil^."] = "在下一區域，先往北走，再從左側樓梯下去。沿這條路一直走到 ^Gurtogg Bloodboil^。",
    ["In the next area, kill several waves of trash. After killing ^Shanna Sparkfizz^, jump in the pipe to reach ^Siegecrafter Blackfuse^."] = "在下一個區域，殺死幾波小怪。殺死^Shanna Sparkfizz^後，跳入管道到達^Siegecrafter Blackfuse^。",
    ["In the next area, move ahead into the cave to engage ^Tortos^."] = "在下一個區域，繼續進入洞穴與 ^Tortos^ 交戰。",
    ["In the next area, take a right and travel south until you reach ^Akama^. Talk to him to begin the battle against ^Shade of Akama^."] = "在下一區域，右轉並往南走，直到抵達 ^Akama^。與他交談，開始與 ^Shade of Akama^ 的戰鬥。",
    ["In the next area, talk to ^Wrathion^ to trigger a cutscene, then kill some adds to start the fight with ^Carapace of N'Zoth^."] = "在下一個區域中，與^Wrathion^交談以觸發過場動畫，然後殺死一些小怪以開始與^Carapace of N'Zoth^的戰鬥。",
    ["In the next area, work your way down the platforms and follow the path to ^General Vezax^. See special note for |cffF259C7Hard Mode|r."] = "在下一個區域逐層向下，通過平台並沿路前往^General Vezax^。請查看|cffF259C7困難模式|r特別提示。",
    ["In the next area, you will pass through the spot where you killed ^Shadow-Lord Iskar^ previously. Continue following the path around, eventually reaching ^Fel Lord Zakuun^."] = "在下一個區域，你將經過你之前殺死^Shadow-Lord Iskar^的地方。繼續沿著周圍的路徑前進，最終到達^Fel Lord Zakuun^。",
    ["In the next building, you will find ^Sha of Violence^ straight ahead."] = "在下一棟建築內，^Sha of Violence^ 就在正前方。",
    ["In the next room, ^Flamegor^ will be flying around right in front of you."] = "下一個房間裡，^Flamegor^會在你正前方飛行。",
    ["Inside ^Court of the Highborne^, take a left and you will find ^Magister Kalendris^ standing against the western wall."] = "進入 ^Court of the Highborne^ 後左轉，會在西側牆邊找到 ^Magister Kalendris^。",
    ["Inside ^Defiant Ramparts^, follow the path to climb some stairs. Kill the last trash pack to spawn ^Assault of the Zaqali^."] = "在^Defiant Ramparts^內，沿著小路爬一些樓梯。殺死最後一個小怪群以出現 ^Assault of the Zaqali^。",
    ["Inside ^Iron Assembly^, follow the path around to ^Beastlord Darmac^."] = "在 ^Iron Assembly^ 內，沿著路徑前往 ^Beastlord Darmac^。",
    ["Inside ^Orgrimmar^, move ahead into the boss tower to fight ^Kor'kron Dark Shaman^."] = "在 ^Orgrimmar^ 內，前進進入 首領 塔與 ^Kor'kron Dark Shaman^ 戰鬥。",
    ["Inside ^The Construct Quarter^, stick to the left and follow the path around to reach ^Patchwerk^."] = "進入 ^The Construct Quarter^ 後，保持靠左並沿路前往 ^Patchwerk^。",
    ["Inside ^The Heart of the Empire^, follow the path around to find some NPCs mourning over the corpse of ^King Rastakhan^. Talk to ^Otoye^ to be switched to Alliance temporarily."] = "在 ^The Heart of the Empire^ 內，沿著周圍的路徑尋找一些 NPC，他們正在為 ^King Rastakhan^ 的屍體哀悼。與^Otoye^交談以暫時切換到聯盟。",
    ["Inside ^The Military Quarter^, follow the path to reach some stairs. Go down and cross the room to reach ^Instructor Razuvious^."] = "進入 ^The Military Quarter^ 後，沿路前往樓梯。下樓並穿過房間即可抵達 ^Instructor Razuvious^。",
    ["Inside ^The Nightspire^, clear trash around the room to begin the encounter with ^Grand Magistrix Elisande^."] = "在 ^The Nightspire^ 內，清除房間周圍的小怪，開始與 ^Grand Magistrix Elisande^ 相遇。",
    ["Inside ^The Plague Quarter^, follow the path south to reach ^Noth the Plaguebringer^."] = "進入 ^The Plague Quarter^ 後，沿路向南前往 ^Noth the Plaguebringer^。",
    ["Inside Firelands"] = "火焰之地內部",
    ["Inside ICC"] = "冰冠城塞內",
    ["Inside the ^Cleft of Shadows^, jump off to the left and head into another tunnel."] = "在 ^Cleft of Shadows^ 內，向左側跳下並進入另一條隧道。",
    ["Inside the ^Hall of Crafting^, you will find ^Fineous Darkvire^ patrolling the ramps."] = "在 ^Hall of Crafting^ 中，會找到在坡道上巡邏的 ^Fineous Darkvire^。",
    ["Inside the ^Hall of Illusions^, you will find ^Jandice Barov^ at the west end of the room."] = "在 ^Hall of Illusions^ 內，^Jandice Barov^ 位於房間西端。",
    ["Inside the ^Halls of Opulence^, proceed straight ahead to the middle area to engage ^Opulence^."] = "在 ^Halls of Opulence^ 內，直行至中間區域與 ^Opulence^ 交戰。",
    ["Inside the ^Precipice of Dreams^, follow the path all the way west to kill ^Za'qul, Harbinger of Ny'alotha^."] = "在^Precipice of Dreams^內，沿著小路一直向西殺死^Za'qul, Harbinger of Ny'alotha^。",
    ["Inside the ^Roost of Ji-Kun^, make your way up and around the long series of paths and stairwells until you reach the platform of ^Ji-Kun^. Avoid the snails; they will still 1-shot you."] = "在 ^Roost of Ji-Kun^ 內，沿著一長串的小路和樓梯間向上走，直到到達 ^Ji-Kun^ 的平台。避開蝸牛；他們仍然會向你開一槍。",
    ["Inside the boss room, head straight ahead to engage ^Opulence^."] = "在首領房間內，徑直向前與^Opulence^交戰。",
    ["Inside the building, take a series of lefts as you work your way around to ^Festergut^."] = "進入建築後，連續左轉，繞行前往^Festergut^。",
    ["Inside the next tunnel, follow the long path to reach ^General Nazgrim^."] = "在下一個隧道內，沿著長路到達^General Nazgrim^。",
    ["Inside the raid, talk to ^Lady Jaina Proudmoore^ to start the encounter with ^Rage Winterchill^."] = "在團隊副本內，與 ^Lady Jaina Proudmoore^ 交談，開始與 ^Rage Winterchill^ 的戰鬥。",
    ["Interrupt/kill both trees to start the fight. When she casts Weaver's Burden on you, run it away from your primary position to drop it out of the way. During intermission(s), interrupt/kill adds."] = "打斷/殺死兩棵樹來開始戰鬥。當她對你施放編織者的負擔時，將其從你的主要位置跑開，將其扔到一邊。在中場休息期間，中斷/終止會增加。",
    ["Into chapel for Whitemane"] = "進入禮拜堂找 Whitemane",
    ["Jaina then Portal"] = "珍娜然後傳送門",
    ["Jaina, then east to the encampment"] = "Jaina 後往東去營地",
    ["Jump below for Viscous Fallout"] = "跳到下層找 Viscous Fallout",
    ["Jump between platforms, killing each of his limbs."] = "在平台之間跳躍，殺死他的四肢。",
    ["Jump down to the lower middle section of the map to reach ^Viscous Fallout^. You can collect more parachutes in the small box by the ledge."] = "跳到地圖下方中央區域到達 ^Viscous Fallout^。可在邊緣旁的小箱子里拿到更多降落傘。",
    ["Jump down to Viscous Fallout"] = "跳下去找 Viscous Fallout",
    ["Jump down"] = "跳下來",
    ["Jump down, take door to Prison"] = "跳下去，從門進入 Prison",
    ["Jump from West -> North -> East and kill them all within 60 seconds of eachother."] = "從西->北->東跳，並在 60 秒內將他們全部殺死。",
    ["Jump in hole behind boss"] = "跳進首領後方的洞",
    ["Jump in Hole"] = "跳進洞裡",
    ["Jump in hole"] = "跳入洞中",
    ["Jump in Lava (Heroic)"] = "跳入熔岩（英雄）",
    ["Jump in Lava"] = "跳入熔岩",
    ["Jump in lava"] = "跳進熔岩",
    ["Jump in purple circle"] = "跳入紫色圓圈",
    ["Jump in Purple Circle"] = "跳進紫色圓圈",
    ["Jump in purple Portal"] = "跳入紫色傳送門",
    ["Jump in Sewer"] = "跳入下水道",
    ["Jump in the lava to die, and you will respawn at the raid entrance."] = "跳入熔岩中死去，然後你會在副本入口處重生。",
    ["Jump in the lava to die. You will respawn at the entrance. |cffffffff(Heroic Only)|r"] = "跳入熔岩而死。您將在入口處重生。 |cffffffff（僅限英雄）|r",
    ["Jump in to meet Mythrax"] = "跳下去前往密斯拉克斯",
    ["Jump in tunnel"] = "跳進隧道",
    ["Jump in water, west to Pythas"] = "跳入水中，向西到 Pythas",
    ["Jump into Portal"] = "跳入傳送門",
    ["Jump ledge to Sassz'ine"] = "跳下平台前往薩絲琳",
    ["Jump off and die"] = "跳下去死掉",
    ["Jump off Ledge"] = "跳下壁架",
    ["Jump off Platform"] = "跳下平台",
    ["Jump off the back of the platform to die and respawn at the entrance."] = "從平台後面跳下死亡並在入口處重生。",
    ["Jump off the ledge behind the final boss to respawn at the ^Challenge Gong^. Run back into the tree, then jump to the lower floor and run out."] = "從最終首領身後的平台邊緣跳下，可在 ^Challenge Gong^ 處復活。跑回樹內，然後跳到下層並離開。",
    ["Jump off the ledge to your death, and you will respawn at the raid exit."] = "從壁架上跳下去死掉，然後你會在團隊出口處重生。",
    ["Jump off to respawn"] = "跳下重生",
    ["Jump off, south to Ironbark"] = "跳下平台，向南到 Ironbark",
    ["Jump!"] = "跳！",
    ["Kill (8) waves of trash and the boss will come.  Infernals will drop out of the sky all over the area."] = "擊殺 (8) 波小怪後，首領就會出現。  地獄火會從天空落到整個區域。",
    ["Kill (8) waves of trash and the boss will come.  Some waves will include gargoyles in the back area."] = "擊殺 (8) 波小怪後，首領就會出現。  部分波次會在後方區域出現石像鬼。",
    ["Kill (8) waves of trash and the boss will come."] = "擊殺 (8) 波小怪後，首領就會出現。",
    ["Kill 5-6 waves until the boss finally comes. You can bang the ^Challenge Gong^ after each wave to speed up the process."] = "擊殺 5-6 波敵人，直到首領出現。每波結束後都可以敲擊 ^Challenge Gong^ 來加快進度。",
    ["Kill ^Nythendra^, then talk to ^Malfurion Stormrage^ to skip to ^Cenarius^."] = "殺死^Nythendra^，然後與^Malfurion Stormrage^交談以跳至^Cenarius^。",
    ["Kill aboms to spawn Ramstein"] = "擊殺憎惡以召出 Ramstein",
    ["Kill Archimonde"] = "殺死阿克蒙德",
    ["Kill Argus"] = "殺死阿古斯",
    ["Kill Cannons"] = "殺炮",
    ["Kill Drest'agath"] = "殺死德雷阿加絲",
    ["Kill East Mini-boss"] = "擊殺東側小首領",
    ["Kill elementals to start Yan-Zhu"] = "擊殺元素開啟 Yan-Zhu",
    ["Kill Fyrakk"] = "殺死弗拉克",
    ["Kill Gizrul when he appears"] = "Gizrul 出現後將其擊殺",
    ["Kill Gordok nearby"] = "擊殺附近的 Gordok",
    ["Kill Gul'dan"] = "殺死古爾丹",
    ["Kill Guldan"] = "殺死古爾丹",
    ["Kill Iron Reaver"] = "殺死鋼鐵掠奪者",
    ["Kill monkeys along path"] = "沿路擊殺猴子",
    ["Kill monkeys to spawn Ook-Ook"] = "擊殺猴子召出 Ook-Ook",
    ["Kill N'Zoth"] = "殺死恩佐斯",
    ["Kill Phalanx by east door"] = "擊殺東門旁的 Phalanx",
    ["Kill Sergeant Bly"] = "擊殺 Sergeant Bly",
    ["Kill several waves"] = "擊殺數波敵人",
    ["Kill Slimes then Experiments"] = "殺死史萊姆然後進行實驗",
    ["Kill South Mini-boss"] = "擊殺南側小首領",
    ["Kill Spazzring upstairs"] = "擊殺樓上的 Spazzring",
    ["Kill Striker Ga'dok"] = "擊殺 Striker Ga'dok",
    ["Kill Summoners then Mannoroth"] = "殺死召喚者然後瑪諾洛斯",
    ["Kill Sylvanas"] = "殺死希爾瓦娜斯",
    ["Kill the ^Ashtongue Channelers^ and the boss will start slowly moving towards ^Akama^. When he reaches ^Akama^, you can kill him."] = "擊殺 ^Ashtongue Channelers^ 後，首領會開始慢慢往 ^Akama^ 移動。等他抵達 ^Akama^ 後，就可以擊殺他。",
    ["Kill the ^Sik'Thik Warden^ to trigger some dialog, and then talk to ^Yang Ironclaw^ to begin the encounter with ^Commander Vo'jak^."] = "擊殺 ^Sik'Thik Warden^ 觸發對話，然後與 ^Yang Ironclaw^ 交談，開始與 ^Commander Vo'jak^ 的戰鬥。",
    ["Kill the enemy king before yours dies. The easy button: take control of your king and spam Heroism or Bloodlust until it's over. It takes a few minutes, but it works."] = "在你的國王死亡前擊殺敵方國王。最簡單的方法：控制你的國王，然後不停使用 Heroism 或 Bloodlust，直到結束。需要幾分鐘，但確實有效。",
    ["Kill The Jailer"] = "殺死獄卒",
    ["Kill the opening trash packs, and click the large artifact on either side of the bridge to open a path to skip straight to ^Blackhand^."] = "清理入口處的小怪，然後點擊橋任一側的大型神器，開啟一條可直接跳到 ^Blackhand^ 的道路。",
    ["Kill the slimes to spawn ^The Forgotten Experiments^."] = "殺死史萊姆以出現 ^The Forgotten Experiments^。",
    ["Kill trash in the boss room to trigger some dialog and start the encounter with ^King Rastakhan^."] = "殺死首領房間中的小怪以觸發一些對話並開始與 ^King Rastakhan^ 的戰鬥。",
    ["Kill Trash to Spawn Shannox"] = "清理小怪，召出沙恩諾克斯",
    ["Kill Trash to Unlock Door"] = "殺死小怪來解鎖門",
    ["Kill trash until door opens"] = "清理敵人直到門開啟",
    ["Kill trash until harpoons become active. Use an active harpoon (4) times to bring down the boss, then kill him."] = "清理敵人，直到魚叉可用。使用可用的魚叉（4）次把首領拉下來，然後將其擊殺。",
    ["Kill trash waves until the south tower reaches 100%. Then climb the south tower, and shoot ^Galakras^ as many times as you can. Kill some more trash on the ground level until ^Galakras^ drops to the ground."] = "殺死小怪波直到南塔達到100%。然後爬上南塔，盡可能多地射擊^Galakras^。在地面上殺死更多小怪，直到 ^Galakras^ 掉落到地面。",
    ["Kill Volcanius then Eranog"] = "殺死沃爾坎尼烏斯然後殺死埃拉諾格",
    ["Kill Volcanius"] = "殺死沃爾坎尼斯",
    ["Kill Warlord Zon'ozz"] = "殺死督軍佐奧茲",
    ["Kill waves of trash until the middle gate opens. Continue killing trash on both sides until they stop spawning, then pull ^Gothik^ down from the balcony to kill him."] = "清理一波波小怪，直到中間的大門開啟。繼續清理兩側的小怪，直到不再重新整理，然後把 ^Gothik^ 從陽台上引下來並擊殺他。",
    ["Kill West Mini-boss"] = "擊殺西側小首領",
    ["Kill Wrathion"] = "殺死怒西昂",
    ["Kill Yor'sahj"] = "殺死約薩吉",
    ["Kill Zeal then Mineshaft"] = "殺死熱心然後殺死礦井",
    ["Kill Zon'ozz"] = "殺死佐諾茲",
    ["Kirin Tor Portal"] = "肯瑞托傳送門",
    ["Leave instance group via LFG tool."] = "透過隊伍搜尋器離開副本隊伍。",
    ["Leave instance group via LFG tool.\n\nNote: If you plan to visit the ^Waking Dream^ wing to kill ^N'Zoth^, you must have ^Ashjra'kamas, Shroud of Resolve^ in your inventory for the Queueing NPC to present the option."] = "透過隊伍搜尋器離開副本隊伍。\n\n注意：若要進入 ^Waking Dream^ 分區擊殺 ^N'Zoth^，你的背包中必須有 ^Ashjra'kamas, Shroud of Resolve^，排隊 NPC 才會提供該選項。",
    ["Leave via LFG Tool"] = "透過隊伍搜尋器離開",
    ["Ledge jump behind final boss"] = "從最終首領後方平台跳下",
    ["Left at fork for Anacondra"] = "岔路左轉到 Anacondra",
    ["Left Elevator down"] = "左電梯向下",
    ["Left into tunnels"] = "左轉進入隧道",
    ["Left path to Hogger"] = "沿左側道路到 Hogger",
    ["Left path to Wise Mari"] = "走左路到 Wise Mari",
    ["Left portal to enter raid"] = "左側傳送門進入團隊副本",
    ["Left to Anub'Rekhan"] = "左轉前往阿努佈雷坎",
    ["Left to Archives of Eternity"] = "留給永恆的檔案",
    ["Left to Beth'tilac"] = "前往貝絲提拉克",
    ["Left to Desolate Host"] = "留給荒涼的主人",
    ["Left to Elevator"] = "左轉至電梯",
    ["Left to Huntsman"] = "往左前往 Huntsman",
    ["Left to Magister Kalendris"] = "左轉到 Magister Kalendris",
    ["Left to Maut"] = "左轉前往莫特",
    ["Left to Onyx Lab"] = "左轉前往瑪瑙實驗室",
    ["Left to Quarry of Infusion"] = "留給輸液採石場",
    ["Left to Scorched Hall"] = "左轉前往燒焦大廳",
    ["Left to The Elemental Conclave"] = "前往元素議會",
    ["Left to Zakuun"] = "留給扎庫恩",
    ["Legacy of Scholomance requires a one-time attunement that starts with {item}, dropped by ^Doctor Theolen Krastinov^, a Heroic-only rare that spawns after ^Rattlegore^ dies. After defeating ^Darkmaster Gandling^, use the toy on the pile of bones to summon ^Eva Sarkhoff^ and accept her quest. Once attuned, use {item2} at Caer Darrow to enter."] = "通靈學院傳承需要完成一次性解鎖，起點是 {item}。該物品由 ^Doctor Theolen Krastinov^ 掉落；他是僅在英雄難度下、且 ^Rattlegore^ 死亡後才會出現的稀有怪。擊敗 ^Darkmaster Gandling^ 後，在骨堆上使用該玩具召喚 ^Eva Sarkhoff^ 並接受她的任務。解鎖後，在 Caer Darrow 使用 {item2} 進入。",
    ["Legacy of Scholomance"] = "通靈學院傳承",
