    ["Light Brazier (2)"] = "點燃火盆（2）",
    ["Light's Breach Portal"] = "聖光突破傳送門",
    ["Location: Butcher's Sanctum, past ^Rattlegore^"] = "位置：屠夫聖所，位於 ^Rattlegore^ 後方",
    ["Location: First level. Across the hall from ^Highlord Omokk^"] = "位置：第一層。^Highlord Omokk^ 對面的大廳",
