    ["Loop north to Koranthal"] = "繞行向北到 Koranthal",
    ["Loop your way around the path and you will see ^Queen Azshara^ trapped. Clear the trash to engage ^Dark Inquisitor Xanesh^."] = "沿著小路繞一圈，您會看到 ^Queen Azshara^ 被困。清除小怪以參與^Dark Inquisitor Xanesh^。",
    ["Magma Orb"] = "熔岩寶珠",
    ["Make your way down the spiral, following the path to reach ^Shad'har the Insatiable^."] = "沿著螺旋線向下走，沿著路徑到達^Shad'har the Insatiable^。",
    ["Make your way up the path and stay to the right and find the map exit labeled ^The Ritual Chamber^."] = "沿著路徑向上走，靠右行駛，找到標有 ^The Ritual Chamber^ 的地圖出口。",
    ["Malfurion then Iris"] = "瑪法里恩然後艾麗絲",
