    ["Moroes in Banquet Hall"] = "Banquet Hall 內的 Moroes",
    ["Motion Sick Peon"] = "暈動症苦工",
    ["Mount up and follow the path upstairs and across the bridge. Enter the building to the west."] = "上坐騎，沿路上樓並過橋。進入西側建築。",
    ["Mount up and ride north to the boss area. Clear trash until the boss spawns. Vehicles optional.\n\n|cffF259C7HARD MODE:|r Talk to ^Lore Keeper of Norgannon^ at the Expedition Camp to activate the towers, and leave them active during the boss fight."] = "騎上坐騎向北前往首領區域。清理敵人，直到首領出現。載具可用可不用。\n\n|cffF259C7困難模式：|r在遠徵營地與^Lore Keeper of Norgannon^交談以啟動塔樓，並在首領戰期間保持塔樓啟動。",
    ["Mulgore Portal"] = "莫高雷傳送門",
    ["NE to Brackenspore"] = "NE 至 佈雷肯斯波爾",
    ["Nethestrasz then Portal"] = "與奈斯特拉茲交談，再進入傳送門",
    ["Next, continue west down the ramp to find ^Tendris Warpwood^."] = "接著沿坡道向西下行，找到 ^Tendris Warpwood^。",
    ["Next, kill ^General Zarithrian^ to the south."] = "接下來，擊殺南側的^General Zarithrian^。",
