    ["Note: Routing will not be available on this lockout"] = "注意：本次副本鎖定期間無法使用路線導航",
    ["Nuke her. During intermission, kill tentacle(s) on the side platform(s)."] = "核彈她。中場休息時，殺死側面平台上的觸手。",
    ["Nuke her. If the fight extends into Phase 2, jump off the boat and make your way through the snow to find ^Jaina^ and finish her off."] = "核彈她。如果戰鬥延續到第二階段，跳下船，穿過雪地找到 ^Jaina^ 並乾掉她。",
    ["NW Stairwell"] = "西北樓梯間",
    ["NW to Butcher"] = "西北至屠夫",
    ["Oblivion stacks don't matter anymore, but avoid swirly/portal-looking areas on the ground. Stay away from the edge."] = "湮滅堆疊不再重要，但要避免地面上看起來像漩渦/傳送門的區域。遠離邊緣。",
    ["Old Keyring"] = "Old Keyring",
    ["On LFR Difficulty, this boss can also drop any LFR token for any gear slot."] = "在隨機團隊難度下，此首領還可以掉落任意裝備欄位的隨機團隊代幣。",
    ["On the beach, your goal is to destroy (7) ^Kor'kron Cannons^. Click the ^Spike Mines^ next to each cannon to destroy them."] = "在海灘上，您的目標是摧毀 (7) ^Kor'kron Cannons^。點擊每門大炮旁邊的 ^Spike Mines^ 來摧毀它們。",
    ["On the other side of the gate, proceed ahead to engage ^Iron Qon^."] = "在大門的另一側，繼續前進以接合 ^Iron Qon^。",
    ["Once in the ^Ring of Containment^, head to the leftmost map exit labeled ^Archives of Eternity^."] = "進入 ^Ring of Containment^ 後，前往最左側標記為 ^Archives of Eternity^ 的地圖出口。",
    ["Once inside ^Artifact Storage^, continue forward and click on the ^Secured Stockpile of Pandaren Spoils^ to begin the ^Spoils of Pandaria^ encounter."] = "進入 ^Artifact Storage^ 後，繼續前進並點擊 ^Secured Stockpile of Pandaren Spoils^ 開始戰鬥 ^Spoils of Pandaria^。",
    ["Once inside ^Loa's Sanctum^, follow the path straight ahead to engage ^Conclave of the Chosen^."] = "進入 ^Loa's Sanctum^ 後，沿著正前方的路徑與 ^Conclave of the Chosen^ 交戰。",
    ["Once inside ^Moonglade^, work your way down to ^Cenarius^ and kill him."] = "進入 ^Moonglade^ 後，一路走到 ^Cenarius^ 並殺死他。",
    ["Once inside ^Mulgore^, follow the path around, and clear the trash on your way to ^Elerethe Renferal^."] = "進入 ^Mulgore^ 後，沿著周圍的小路走，並清除前往 ^Elerethe Renferal^ 途中的小怪。",
    ["Once it becomes available, click the Gunship Cannon and shoot at the enemy ship a few times to win the battle."] = "火炮可用後，點擊飛艇火炮並向敵方飛艇射擊數次即可獲勝。",
    ["Once the door opens, proceed through it and climb some stairs to reach ^Star Augur Etraeus^."] = "門開啟後，穿過門並爬一些樓梯到達^Star Augur Etraeus^。",
    ["Once the fight begins, click the ^Lever^ to open the gate and make your way through the gauntlet, killing all trash along the way. In the final hallway approaching ^Thorim^, go AROUND the large circles on the ground to avoid lengthy stuns.\n\n|cffF259C7HARD MODE:|r Reach him within 3 minutes of starting the gauntlet."] = "戰鬥開始後，點擊^Lever^開啟大門，沿挑戰路線前進並清理所有敵人。在接近^Thorim^的最後一段走廊中，繞開地面上的大圓圈，以免被長時間昏迷。\n\n|cffF259C7困難模式：|r在挑戰開始後的3分鐘內到達他身邊。",
    ["Once you arrive in ^Feast of Arrogance^, follow the path to find ^The Council of Blood^ at the far end of the room."] = "到達 ^Feast of Arrogance^ 後，沿著路徑在房間的遠端找到 ^The Council of Blood^。",
    ["Once you arrive in the ^Eye of Eternity^, click ^The Focusing Iris^ to start the encounter with ^Hagara the Stormbinder^."] = "到達 ^Eye of Eternity^ 後，點擊 ^The Focusing Iris^ 開始與 ^Hagara the Stormbinder^ 的戰鬥。",
    ["Once you enter the ^Elarian Sanctuary^, approach the ^Essence of Eonar^ (blue floating orb), and interact with it to begin the encounter for ^Eonar the Life-Binder^."] = "一旦你進入^Elarian Sanctuary^，接近^Essence of Eonar^（藍色浮動球體），並與其互動以開始^Eonar the Life-Binder^的戰鬥。",
    ["Once you enter the building, kill several waves of enemies. After defeating the two senior students, you can go up the stairs."] = "進入建築後，擊殺數波敵人。擊敗兩名高年級學生後即可上樓。",
    ["Once you land, take the middle (and final) path labeled ^The Clutchwarren^."] = "著陸後，走中間（也是最後）一條標有 ^The Clutchwarren^ 的路徑。",
    ["Once you reach ^Helheim^, follow the path around to find ^Guarm^."] = "到達 ^Helheim^ 後，沿著周圍的路徑找到 ^Guarm^。",
    ["Once you reach ^Master's Terrace^, loop around and click on the ^Blackened Urn^. After a short delay, ^Nightbane^ will fly in to be killed by you."] = "抵達 ^Master's Terrace^ 後，繞一圈並點擊 ^Blackened Urn^。稍等片刻後，^Nightbane^ 會飛來供你擊殺。",
    ["Once you reach ^Shal'dorei Terrace^, make your way over to ^High Botanist Tel'arn^ to begin the encounter."] = "到達 ^Shal'dorei Terrace^ 後，前往 ^High Botanist Tel'arn^ 開始戰鬥。",
    ["Once you reach ^The Observation Ring^, you will find ^Auriaya^ slowly circling the room."] = "到達^The Observation Ring^後，你會看到^Auriaya^正在房間內緩慢巡邏。",
    ["Once you reach ^The Tasting Room^, kill the two large elementals in the middle of the room to start the encounter with ^Yan-Zhu the Uncasked^."] = "到達 ^The Tasting Room^ 後，擊殺房間中央的兩個大型元素，開始與 ^Yan-Zhu the Uncasked^ 的戰鬥。",
    ["Once you reach the ^Ring of Containment^, take a right and head for the map exit labeled ^Gallery of Failures^."] = "到達 ^Ring of Containment^ 後，右轉並前往標記為 ^Gallery of Failures^ 的地圖出口。",
    ["Once you reach the bottom of the elevator, take the southern path to reach ^Hans'gar and Franzok^. After a brief dialog, kill the trash to start the encounter."] = "到達電梯底部後，沿南邊小路到達^Hans'gar and Franzok^。簡短的對話後，殺死小怪即可開始戰鬥。",
    ["Once you reach the large room with the monkeys, kill monkeys until the counter reaches 40/40 to spawn ^Ook-Ook^."] = "到達有猴子的大房間後，持續擊殺猴子，直到計數達到 40/40 以召出 ^Ook-Ook^。",
    ["Once you reach the top floor, go slightly east to deactivate the second ^Shield Generator^."] = "到達頂層後，稍向東走，關閉第二個 ^Shield Generator^。",
    ["Once you reach the top of the elevator, follow the long path south until you reach the final boss, ^Xin the Weaponmaster^."] = "到達電梯頂部後，沿長路向南前進，直到最終首領 ^Xin the Weaponmaster^。",
    ["Once you reach the top of the elevator, follow the path to the north to reach ^The Crucible^."] = "到達電梯頂部後，沿著小路向北到達^The Crucible^。",
    ["Once you reach the top of the stairs, follow the path ahead to reach ^Prince Malchezaar^."] = "抵達樓梯頂端後，沿前方路線繼續前往 ^Prince Malchezaar^。",
    ["Once you're in mid-flight, talk to ^Sky Captain Swayze^ again to begin the encounter with ^Warmaster Blackhorn^."] = "飛行途中，再次與 ^Sky Captain Swayze^ 交談以開始與 ^Warmaster Blackhorn^ 的戰鬥。",
    ["Open all twelve Relic Coffers to wake the vault and spawn ^Watchman Doomgrip^. Defeating him opens the hidden door to the Safe."] = "打開全部十二個遺物寶箱以喚醒寶庫並召出 ^Watchman Doomgrip^。擊敗他會打開通往保險箱的隱藏門。",
    ["Open Masked Gate"] = "開啟蒙面之門",
    ["Open the door in front of you to land in ^Horridon^'s room. After a brief dialog, kill the boss."] = "開啟你面前的門，進入^Horridon^的房間。簡短對話後，殺死首領。",
