    ["Pickpocketing Hagara starts a long Rogue chain that eventually rewards {item1} and {item2}. Both are listed under Madness of Deathwing."] = "偷竊Hagara會開啟一條漫長的盜賊任務線，最後獎勵{item1}與{item2}。兩者都列在Madness of Deathwing下。",
