    ["Travel along the ledge into the next room. Stick to one side of the room to avoid overlapping auras, and click ^Suppression Devices^ to temporarily disable them as you move through the room."] = "沿平台邊緣進入下一個房間。貼著房間一側前進以避免光環重疊，並點擊^Suppression Devices^暫時關閉它們。",
    ["Tribute Chest"] = "貢品寶箱",
    ["Tribute loot comes from the Gordok Tribute chest: defeat King Gordok while the wing's other bosses still live, then speak with Mizzle the Crafty to be crowned and claim the chest."] = "貢品戰利品來自戈多克貢品寶箱：在該區其他首領仍存活時擊敗戈多克大王，然後與狡猾的米茲勒交談接受加冕並領取寶箱。",
    ["Triumph and Conquest appearances are shared, "] = "凱旋與征服外觀共用， ",
    ["Triumph sold for {item} + Gold"] = "凱旋可用{item} + 金幣購買",
    ["Try to kill them 1 at a time or they could despawn."] = "盡量一次只擊殺一個，否則它們可能會消失。",
    ["Turn in tokens for Qiraji weapons"] = "用代幣兌換其拉武器",
    ["Turn in tokens for Tier pieces"] = "用代幣兌換套裝部件",
