    ["Up the northern stairs"] = "走北側樓梯上去",
    ["Up the ramps to Naj'entus"] = "沿斜坡上去前往 Naj'entus",
    ["Up to Broodkeeper Diurna"] = "直至育巢守護者迪烏娜",
