    ["Valiant Bressia"] = "Valiant Bressia",
    ["Valiant Laradia"] = "Valiant Laradia",
    ["Vent Behind Neltharion then Jump"] = "奈薩里奧身後的通風口，然後跳下",
    ["Vent"] = "通風口",
    ["Verdant Dreambreaker"] = "蒼翠破夢者",
    ["View special note"] = "查看特殊說明",
    ["Viscidus requires you to freeze him and then shatter him with physical/melee damage within a time limit. For most classes, soloing this will require gimmicky strategies involving special trinkets/toys. You can {skip} this boss if you don't have the kit or the patience for it."] = "Viscidus需要先被冰凍，再於限時內用物理/近戰傷害擊碎。對大多數職業而言，單刷需要特殊飾品/玩具等技巧。若沒有合適的裝備或耐心，可以{skip}這個首領。",
    ["Wait for transport"] = "等待運輸",
    ["Wait for Tsulong"] = "等待祖龍",
    ["Walk into (3) Floor Teleporters"] = "走進 (3) 層傳送器",
    ["Walk into the ^beam of light^ and click the ^Extra Action Button^ to trigger a cutscene. After the cutscene, go up the stairs and jump off the ledge."] = "走進^beam of light^並點擊^Extra Action Button^觸發過場動畫。過場動畫結束後，上樓梯並從壁架上跳下來。",
    ["Walk over anima orbs to collect them, and bring them to ^Prince Renathal^ to free him."] = "走過心能球收集它們，並將它們帶到 ^Prince Renathal^ 以釋放他。",
    ["Warden Thul'tok then Portal"] = "典獄長蘇托克和傳送門",
